<script setup lang="ts">import{ref,onMounted}from'vue';import{api,ApiError}from'../api';defineProps<{open:boolean;theme:string}>();defineEmits<{close:[];theme:[value:string];unpair:[]}>();const pairPwdStatus=ref<boolean|undefined>(undefined),newPwd=ref(''),pwdBusy=ref(false),pwdError=ref(''),pwdOk=ref('');async function loadStatus(){try{pairPwdStatus.value=(await api.pairStatus()).password}catch{pairPwdStatus.value=undefined}}async function setPwd(){if(pwdBusy.value)return;pwdError.value='';pwdOk.value='';if(newPwd.value.trim().length<8){pwdError.value='密码至少 8 位';return}pwdBusy.value=true;try{await api.setPairPassword(newPwd.value.trim());newPwd.value='';pwdOk.value='已保存配对密码';pwdError.value='';await loadStatus()}catch(e){pwdError.value=e instanceof ApiError&&e.status===403?'仅可从电脑本机设置':e instanceof Error?e.message:'保存失败';pwdOk.value=''}finally{pwdBusy.value=false}}async function clearPwd(){if(pwdBusy.value)return;pwdError.value='';pwdOk.value='';pwdBusy.value=true;try{await api.clearPairPassword();pwdOk.value='已清除配对密码';pwdError.value='';await loadStatus()}catch(e){pwdError.value=e instanceof ApiError&&e.status===403?'仅可从电脑本机设置':e instanceof Error?e.message:'清除失败';pwdOk.value=''}finally{pwdBusy.value=false}}onMounted(loadStatus);</script>
<template><div v-if="open" class="viewer-backdrop" @click.self="$emit('close')"><section class="settings-surface"><header><div><small>设备与外观</small><h2>设置</h2></div><button class="icon-button" @click="$emit('close')">×</button></header><label>主题<select :value="theme" @change="$emit('theme',($event.target as HTMLSelectElement).value)"><option value="system">跟随系统</option><option value="light">浅色</option><option value="dark">深色</option></select></label><div class="settings-row password-config-row"><div><strong>配对密码</strong><small>本机设置后，远程端可用密码配对并跨电脑重启自动重连。{{pairPwdStatus===true?'当前：已设置':pairPwdStatus===false?'当前：未设置':''}}</small><div class="password-input"><input v-model.trim="newPwd" type="password" placeholder="新密码（至少 8 位）" :disabled="pwdBusy" @keyup.enter="setPwd"><button class="text-button" :disabled="pwdBusy||newPwd.length<8" @click="setPwd">{{pwdBusy?'保存中…':'设置'}}</button><button v-if="pairPwdStatus" class="text-button danger-text" :disabled="pwdBusy" @click="clearPwd">清除</button></div><p v-if="pwdError" class="form-error">{{pwdError}}</p><p v-else-if="pwdOk" class="form-ok">{{pwdOk}}</p></div></div><div class="settings-row"><div><strong>已配对设备</strong><small>凭据仅用于本机连接，界面不会显示令牌。</small></div><button class="danger-button" @click="$emit('unpair')">解除配对</button></div><div class="settings-row"><div><strong>Codex-only</strong><small>此客户端不提供其他 provider 或终端工具箱。</small></div></div></section></div></template>
